async function handleFeed(url, env, cors) {
  const limit = getPageSize(url);
  const sort = url.searchParams.get("sort") === "popular" ? "popular" : "latest";
  const cursor = decodeCursor(url.searchParams.get("cursor"));
  let whereCursor = "";
  const bindings = [];
  if (cursor) {
    if (sort === "popular") {
      const likeCount = Number(cursor.likeCount);
      const publishedAt = Number(cursor.publishedAt);
      const id = safeString(cursor.id);
      if (Number.isFinite(likeCount) && Number.isFinite(publishedAt) && id) {
        whereCursor = `
          AND (
            COALESCE(s.like_count, 0) < ?
            OR (COALESCE(s.like_count, 0) = ? AND t.published_at < ?)
            OR (COALESCE(s.like_count, 0) = ? AND t.published_at = ? AND t.id < ?)
          )`;
        bindings.push(likeCount, likeCount, publishedAt, likeCount, publishedAt, id);
      }
    } else {
      const publishedAt = Number(cursor.publishedAt);
      const id = safeString(cursor.id);
      if (Number.isFinite(publishedAt) && id) {
        whereCursor = `
          AND (
            t.published_at < ?
            OR (t.published_at = ? AND t.id < ?)
          )`;
        bindings.push(publishedAt, publishedAt, id);
      }
    }
  }
  const orderBy = sort === "popular" ? "COALESCE(s.like_count, 0) DESC, t.published_at DESC, t.id DESC" : "t.published_at DESC, t.id DESC";
  const result = await env.DB.prepare(`
    SELECT
      t.*,
      p.nickname AS owner_nickname,
      p.avatar_url AS owner_avatar_url,
      COALESCE(s.like_count, 0) AS like_count,
      COALESCE(s.comment_count, 0) AS comment_count,
      COALESCE(s.play_count, 0) AS play_count
    FROM tracks t
    LEFT JOIN public_profiles p
      ON p.uid = t.owner_uid AND p.is_public = 1
    LEFT JOIN track_stats s
      ON s.track_id = t.id
    WHERE t.is_public = 1
      AND t.status = 'published'
      ${whereCursor}
    ORDER BY ${orderBy}
    LIMIT ?
  `).bind(...bindings, limit + 1).all();
  const rows = result.results || [];
  const hasMore = rows.length > limit;
  const visible = rows.slice(0, limit);
  const items = visible.map(mapTrackRow);
  const last = visible[visible.length - 1];
  const nextCursor = hasMore && last ? encodeCursor(
    sort === "popular" ? {
      likeCount: Number(last.like_count || 0),
      publishedAt: Number(last.published_at || 0),
      id: last.id
    } : {
      publishedAt: Number(last.published_at || 0),
      id: last.id
    }
  ) : null;
  return json({ ok: true, data: { items, nextCursor, sort } }, 200, cors);
}
