function buildFtsQuery(value) {
  const terms = String(value || "").trim().split(/\s+/).map((term) => term.replace(/["*:^~(){}\[\]]/g, "").trim()).filter(Boolean).slice(0, 8);
  if (terms.length === 0) return "";
  return terms.map((term) => `"${term}"*`).join(" AND ");
}
