    const id = safeString(cursor.id);
    if (Number.isFinite(priority) && Number.isFinite(publishedAt) && id) {
      rankedCursorSql = `
        WHERE (
          search_priority > ?
          OR (
            search_priority = ?
            AND (
              published_at < ?
              OR (published_at = ? AND id < ?)
            )
          )
        )`;
      cursorBindings.push(priority, priority, publishedAt, publishedAt, id);
    }
