async function handleTrackComments(url, trackId, env, cors) {
  const track = await env.DB.prepare(`
    SELECT id
    FROM tracks
    WHERE id = ? AND is_public = 1 AND status = 'published'
    LIMIT 1
  `).bind(trackId).first();
  if (!track) {
    return apiError("NOT_FOUND", "\uACF5\uAC1C \uACE1\uC744 \uCC3E\uC744 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4.", 404, cors);
  }
  const limit = getPageSize(url);
  const cursor = decodeCursor(url.searchParams.get("cursor"));
  const bindings = [trackId];
  let whereCursor = "";
  if (cursor) {
    const createdAt = Number(cursor.createdAt);
    const id = safeString(cursor.id);
    if (Number.isFinite(createdAt) && id) {
      whereCursor = `
        AND (
          c.created_at < ?
          OR (c.created_at = ? AND c.id < ?)
        )`;
      bindings.push(createdAt, createdAt, id);
    }
  }
  const result = await env.DB.prepare(`
    SELECT
      c.id,
      c.track_id,
      c.user_uid,
      c.body,
      c.created_at,
      c.updated_at,
      p.nickname,
      p.avatar_url
    FROM comments c
    LEFT JOIN public_profiles p
      ON p.uid = c.user_uid AND p.is_public = 1
    WHERE c.track_id = ?
      AND c.status = 'active'
      ${whereCursor}
    ORDER BY c.created_at DESC, c.id DESC
    LIMIT ?
  `).bind(...bindings, limit + 1).all();
  const rows = result.results || [];
  const hasMore = rows.length > limit;
  const visible = rows.slice(0, limit);
  const items = visible.map((row) => ({
    id: row.id,
    trackId: row.track_id,
    userUid: row.user_uid,
    nickname: row.nickname || "",
    avatarUrl: row.avatar_url || "",
    body: row.body,
    createdAt: Number(row.created_at || 0),
    updatedAt: Number(row.updated_at || 0)
  }));
  const last = visible[visible.length - 1];
  const nextCursor = hasMore && last ? encodeCursor({
    createdAt: Number(last.created_at || 0),
    id: last.id
  }) : null;
  return json({ ok: true, data: { items, nextCursor } }, 200, cors);
}
