function getKstPeriodStart(period, nowMs = Date.now()) {
  const KST_OFFSET = 9 * 60 * 60 * 1e3;
  const shifted = new Date(nowMs + KST_OFFSET);
  const year = shifted.getUTCFullYear();
  const month = shifted.getUTCMonth();
  const day = shifted.getUTCDate();
  let startShifted;
  if (period === "daily") {
    startShifted = Date.UTC(year, month, day);
  } else if (period === "weekly") {
    const weekday = shifted.getUTCDay();
    const daysSinceMonday = (weekday + 6) % 7;
    startShifted = Date.UTC(year, month, day - daysSinceMonday);
  } else if (period === "monthly") {
    startShifted = Date.UTC(year, month, 1);
  } else {
    throwApi("INVALID_TOP10_PERIOD", "TOP10 \uAE30\uAC04 \uAC12\uC774 \uC62C\uBC14\uB974\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4.", 400);
  }
  return startShifted - KST_OFFSET;
}
