async function handleTop10(url, env, cors) {
  const period = safeString(url.searchParams.get("period") || "daily").toLowerCase();
  const startAt = getKstPeriodStart(period);
  const now = Date.now();
  const result = await env.DB.prepare(`
    WITH like_scores AS (
      SELECT l.track_id, COUNT(DISTINCT l.user_uid) AS unique_likes
      FROM likes l
      JOIN tracks owner_track ON owner_track.id = l.track_id
      WHERE l.created_at >= ? AND l.created_at <= ?
        AND l.user_uid <> owner_track.owner_uid
      GROUP BY l.track_id
    ), comment_scores AS (
      SELECT c.track_id, COUNT(DISTINCT c.user_uid) AS unique_commenters
      FROM comments c
      JOIN tracks owner_track ON owner_track.id = c.track_id
      WHERE c.status = 'active' AND c.created_at >= ? AND c.created_at <= ?
        AND c.user_uid <> owner_track.owner_uid
      GROUP BY c.track_id
    )
    SELECT t.*, p.nickname AS owner_nickname, p.avatar_url AS owner_avatar_url,
      COALESCE(s.like_count,0) AS like_count,
      COALESCE(s.comment_count,0) AS comment_count,
      COALESCE(s.play_count,0) AS play_count,
      COALESCE(ls.unique_likes,0) AS period_like_users,
      COALESCE(cs.unique_commenters,0) AS period_comment_users,
      (COALESCE(ls.unique_likes,0) + 2 * COALESCE(cs.unique_commenters,0)) AS rank_score
    FROM tracks t
    LEFT JOIN public_profiles p ON p.uid = t.owner_uid AND p.is_public = 1
    LEFT JOIN track_stats s ON s.track_id = t.id
    LEFT JOIN like_scores ls ON ls.track_id = t.id
    LEFT JOIN comment_scores cs ON cs.track_id = t.id
    WHERE t.is_public = 1 AND t.status = 'published'
      AND (COALESCE(ls.unique_likes,0) > 0 OR COALESCE(cs.unique_commenters,0) > 0)
    ORDER BY rank_score DESC, period_comment_users DESC, period_like_users DESC, t.published_at DESC, t.id DESC
    LIMIT 10
  `).bind(startAt, now, startAt, now).all();
  const items = (result.results || []).map((row, index) => ({
    rank: index + 1,
    score: Number(row.rank_score || 0),
    periodLikeUsers: Number(row.period_like_users || 0),
    periodCommentUsers: Number(row.period_comment_users || 0),
    track: mapTrackRow(row)
  }));
  return json({ ok: true, data: { period, timezone: "Asia/Seoul", startAt, endAt: now, items } }, 200, cors);
}
