async function handleCurated(url, env, cors) {
  const collection = normalizeCollectionKey(url.searchParams.get("collection") || "featured");
  const now = Date.now();
  const rawLimit = Number(url.searchParams.get("limit") || 12);
  const limit = Number.isFinite(rawLimit) ? Math.min(50, Math.max(1, Math.floor(rawLimit))) : 12;
  const result = await env.DB.prepare(`
    SELECT t.*, p.nickname AS owner_nickname, p.avatar_url AS owner_avatar_url,
      COALESCE(s.like_count,0) AS like_count,
      COALESCE(s.comment_count,0) AS comment_count,
      COALESCE(s.play_count,0) AS play_count,
      cp.curator_uid, cp.curator_role, cp.sort_order, cp.starts_at, cp.ends_at
    FROM curated_picks cp
    JOIN tracks t ON t.id = cp.track_id
    LEFT JOIN public_profiles p ON p.uid = t.owner_uid AND p.is_public = 1
    LEFT JOIN track_stats s ON s.track_id = t.id
    WHERE cp.collection_key = ?
      AND (cp.starts_at IS NULL OR cp.starts_at <= ?)
      AND (cp.ends_at IS NULL OR cp.ends_at > ?)
      AND t.is_public = 1 AND t.status = 'published'
    ORDER BY cp.sort_order ASC, cp.updated_at DESC, t.published_at DESC
    LIMIT ?
  `).bind(collection, now, now, limit).all();
  const items = (result.results || []).map((row) => ({
    track: mapTrackRow(row),
    curation: {
      curatorUid: row.curator_uid,
      curatorRole: row.curator_role,
      sortOrder: Number(row.sort_order || 0),
      startsAt: row.starts_at == null ? null : Number(row.starts_at),
      endsAt: row.ends_at == null ? null : Number(row.ends_at)
    }
  }));
  return json({ ok: true, data: { collection, items } }, 200, cors);
}
