async function requireExploreAuth(request) {
  const authHeader = request.headers.get("Authorization") || "";
  const appCheckToken = request.headers.get("X-Firebase-AppCheck") || "";
  if (!authHeader.startsWith("Bearer ") || !appCheckToken) {
    throwApi("AUTHENTICATION_REQUIRED", "\uC778\uC99D\uC774 \uD544\uC694\uD569\uB2C8\uB2E4.", 401);
  }
  const idToken = authHeader.slice(7).trim();
  if (!idToken) {
    throwApi("AUTHENTICATION_REQUIRED", "\uC778\uC99D\uC774 \uD544\uC694\uD569\uB2C8\uB2E4.", 401);
  }
  try {
    const [authResult, appCheckResult] = await Promise.all([
      verifyFirebaseIdToken(idToken),
      verifyFirebaseAppCheck(appCheckToken)
    ]);
    return {
      uid: authResult.uid,
      displayName: authResult.displayName || "",
      email: authResult.email || "",
      picture: authResult.picture || "",
      appId: appCheckResult.appId,
      idToken,
      appCheckToken
    };
  } catch (error) {
    console.warn("[Explore Auth] rejected", error);
    throwApi("INVALID_AUTHENTICATION", "\uC778\uC99D\uC774 \uC720\uD6A8\uD558\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4.", 401);
  }
}
