async function refreshProfileSearchIndex(env, uid) {
  const profile = await env.DB.prepare(`
    SELECT uid, nickname, bio FROM public_profiles WHERE uid = ? AND is_public = 1 LIMIT 1
  `).bind(uid).first();
  const statements = [env.DB.prepare("DELETE FROM profile_search_fts WHERE uid = ?").bind(uid)];
  if (profile) {
    statements.push(env.DB.prepare(`
      INSERT INTO profile_search_fts (uid, nickname, bio) VALUES (?, ?, ?)
    `).bind(uid, profile.nickname || "", profile.bio || ""));
  }
  await env.DB.batch(statements);
}
