async function resolveCuratorAccess(env, authContext) {
  const row = await env.DB.prepare(`
    SELECT role FROM explore_curators WHERE uid = ? AND is_active = 1 LIMIT 1
  `).bind(authContext.uid).first();
  if (row?.role === "master") return "master";
  if (await readFirebaseAdminRole(authContext)) {
    const now = Date.now();
    await env.DB.prepare(`
      INSERT INTO explore_curators (uid, role, is_active, created_by_uid, created_at, updated_at)
      VALUES (?, 'admin', 1, ?, ?, ?)
      ON CONFLICT(uid) DO UPDATE SET role='admin', is_active=1, updated_at=excluded.updated_at
    `).bind(authContext.uid, authContext.uid, now, now).run();
    return "admin";
  }
  if (row?.role === "admin") {
    await env.DB.prepare(`
      UPDATE explore_curators SET is_active = 0, updated_at = ? WHERE uid = ? AND role = 'admin'
    `).bind(Date.now(), authContext.uid).run();
  }
  return null;
}
