async function handleMyFollowing(request, url, env, cors) {
  const authContext = await requireExploreAuth(request);
  const limit = getPageSize(url);
  const cursor = decodeCursor(url.searchParams.get("cursor"));
  const bindings = [authContext.uid];
  let cursorSql = "";
  if (cursor) {
    const followedAt = Number(cursor.followedAt);
    const uid = safeString(cursor.uid);
    if (Number.isFinite(followedAt) && uid) {
      cursorSql = "AND (f.created_at < ? OR (f.created_at = ? AND f.following_uid < ?))";
      bindings.push(followedAt, followedAt, uid);
    }
  }
  const result = await env.DB.prepare(`
    SELECT p.uid, p.nickname, p.avatar_url, p.bio, f.created_at AS followed_at,
      COALESCE(ps.follower_count,0) AS follower_count,
      COALESCE(ps.following_count,0) AS following_count,
      (SELECT COUNT(*) FROM tracks t WHERE t.owner_uid=p.uid AND t.is_public=1 AND t.status='published') AS track_count
    FROM follows f
    JOIN public_profiles p ON p.uid=f.following_uid AND p.is_public=1
    LEFT JOIN profile_stats ps ON ps.uid=p.uid
    WHERE f.follower_uid=? ${cursorSql}
    ORDER BY f.created_at DESC, f.following_uid DESC
    LIMIT ?
  `).bind(...bindings, limit + 1).all();
  const rows = result.results || [];
  const hasMore = rows.length > limit;
  const visible = rows.slice(0, limit);
  const items = visible.map((row) => ({
    uid: row.uid,
    nickname: row.nickname || "",
    avatarUrl: row.avatar_url || "",
    bio: row.bio || "",
    followerCount: Number(row.follower_count || 0),
    followingCount: Number(row.following_count || 0),
    trackCount: Number(row.track_count || 0),
    followedAt: Number(row.followed_at || 0)
  }));
  const last = visible[visible.length - 1];
  return json({ ok: true, data: {
    items,
    nextCursor: hasMore && last ? encodeCursor({ followedAt: Number(last.followed_at || 0), uid: last.uid }) : null
  } }, 200, cors);
}
