async function handleUpsertPublicFolder(request, env, cors) {
  const authContext = await requireExploreAuth(request);
  await enforceUserRateLimit(env, authContext.uid, "folder", RATE_LIMITS.folder);
  const body = await readJsonBody(request, 32768);
  const sourceFolderId = firstNonEmptyString(body.sourceFolderId);
  if (!sourceFolderId || sourceFolderId.length > 256) {
    throwApi("SOURCE_FOLDER_ID_REQUIRED", "\uC6D0\uBCF8 \uD3F4\uB354 ID\uAC00 \uD544\uC694\uD569\uB2C8\uB2E4.", 400);
  }
  const title = normalizePublicFolderTitle(body.title);
  const trackIds = normalizePublicFolderTrackIds(body.trackIds);
  const isPublic = typeof body.isPublic === "boolean" ? body.isPublic : true;
  const now = Date.now();
  let folder = await env.DB.prepare(`
    SELECT id FROM public_folders WHERE owner_uid = ? AND source_folder_id = ? LIMIT 1
  `).bind(authContext.uid, sourceFolderId).first();
  const folderId = folder?.id || `public_folder_${crypto.randomUUID()}`;
  await env.DB.prepare(`
    INSERT INTO public_folders (id, owner_uid, source_folder_id, title, is_public, created_at, updated_at)
    VALUES (?, ?, ?, ?, ?, ?, ?)
    ON CONFLICT(owner_uid, source_folder_id) DO UPDATE SET
      title = excluded.title,
      is_public = excluded.is_public,
      updated_at = excluded.updated_at
  `).bind(folderId, authContext.uid, sourceFolderId, title, isPublic ? 1 : 0, now, now).run();
  folder = await env.DB.prepare(`
    SELECT id FROM public_folders WHERE owner_uid = ? AND source_folder_id = ? LIMIT 1
  `).bind(authContext.uid, sourceFolderId).first();
  const resolvedFolderId = String(folder?.id || folderId);
  await replacePublicFolderTracks(env, resolvedFolderId, authContext.uid, trackIds, now);
  return json({ ok: true, data: {
    folderId: resolvedFolderId,
    sourceFolderId,
    title,
    isPublic,
    mappedTrackCount: trackIds === null ? null : trackIds.length
  } }, 200, cors);
}
