async function handleMyPublicFolders(request, env, cors) {
  const authContext = await requireExploreAuth(request);
  const result = await env.DB.prepare(`
    SELECT pf.id, pf.source_folder_id, pf.title, pf.is_public, pf.created_at, pf.updated_at,
      COUNT(pft.track_id) AS mapped_track_count,
      SUM(CASE WHEN t.is_public = 1 AND t.status = 'published' THEN 1 ELSE 0 END) AS public_track_count
    FROM public_folders pf
    LEFT JOIN public_folder_tracks pft ON pft.folder_id = pf.id
    LEFT JOIN tracks t ON t.id = pft.track_id
    WHERE pf.owner_uid = ?
    GROUP BY pf.id
    ORDER BY pf.updated_at DESC, pf.id DESC
  `).bind(authContext.uid).all();
  const items = (result.results || []).map((row) => ({
    id: row.id,
    sourceFolderId: row.source_folder_id,
    title: row.title || "",
    isPublic: Number(row.is_public || 0) === 1,
    mappedTrackCount: Number(row.mapped_track_count || 0),
    publicTrackCount: Number(row.public_track_count || 0),
    createdAt: Number(row.created_at || 0),
    updatedAt: Number(row.updated_at || 0)
  }));
  return json({ ok: true, data: { items } }, 200, cors);
}
