async function handlePublicProfileFolderTracks(url, uid, folderId, env, cors) {
  const folder = await env.DB.prepare(`
    SELECT pf.id
    FROM public_folders pf
    JOIN public_profiles p ON p.uid = pf.owner_uid AND p.is_public = 1
    WHERE pf.id = ? AND pf.owner_uid = ? AND pf.is_public = 1
    LIMIT 1
  `).bind(folderId, uid).first();
  if (!folder) return apiError("NOT_FOUND", "\uACF5\uAC1C \uD3F4\uB354\uB97C \uCC3E\uC744 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4.", 404, cors);
  const limit = getPageSize(url);
  const result = await env.DB.prepare(`
    SELECT t.*, p.nickname AS owner_nickname, p.avatar_url AS owner_avatar_url,
      COALESCE(s.like_count,0) AS like_count,
      COALESCE(s.comment_count,0) AS comment_count,
      COALESCE(s.play_count,0) AS play_count,
      pft.sort_order
    FROM public_folder_tracks pft
    JOIN tracks t ON t.id = pft.track_id
    LEFT JOIN public_profiles p ON p.uid = t.owner_uid AND p.is_public = 1
    LEFT JOIN track_stats s ON s.track_id = t.id
    WHERE pft.folder_id = ? AND t.owner_uid = ?
      AND t.is_public = 1 AND t.status = 'published'
    ORDER BY pft.sort_order ASC, t.published_at DESC, t.id DESC
    LIMIT ?
  `).bind(folderId, uid, limit).all();
  return json({ ok: true, data: { items: (result.results || []).map(mapTrackRow) } }, 200, cors);
}
