async function refreshCommentCount(env, trackId, now) {
  await env.DB.batch([
    env.DB.prepare(`
      INSERT INTO track_stats (track_id, like_count, comment_count, play_count, updated_at)
      VALUES (?, 0, 0, 0, ?)
      ON CONFLICT(track_id) DO NOTHING
    `).bind(trackId, now),
    env.DB.prepare(`
      UPDATE track_stats
      SET comment_count = (
            SELECT COUNT(*)
            FROM comments
            WHERE track_id = ? AND status = 'active'
          ),
          updated_at = ?
      WHERE track_id = ?
    `).bind(trackId, now, trackId)
  ]);
  const stat = await env.DB.prepare(
    "SELECT comment_count FROM track_stats WHERE track_id = ? LIMIT 1"
  ).bind(trackId).first();
  return Number(stat?.comment_count || 0);
}
