async function handleCreateComment(request, env, cors, trackId) {
  const authContext = await requireExploreAuth(request);
  await enforceUserRateLimit(env, authContext.uid, "comment-create", RATE_LIMITS.commentCreate);
  await getPublicTrackForWrite(env, trackId);
  const body = await readJsonBody(request, 4096);
  const commentBody = normalizeCommentBody(body.body);
  const now = Date.now();
  const id = crypto.randomUUID();
  const profile = await upsertPublicProfileFromFirebase(env, authContext, now);
  await env.DB.prepare(`
    INSERT INTO comments (
      id, track_id, user_uid, body, status, created_at, updated_at
    ) VALUES (?, ?, ?, ?, 'active', ?, ?)
  `).bind(id, trackId, authContext.uid, commentBody, now, now).run();
  const commentCount = await refreshCommentCount(env, trackId, now);
  return json(
    {
      ok: true,
      data: {
        comment: {
          id,
          trackId,
          userUid: authContext.uid,
          nickname: profile.nickname,
          avatarUrl: profile.avatarUrl,
          body: commentBody,
          createdAt: now,
          updatedAt: now
        },
        commentCount
      }
    },
    201,
    cors
  );
}
